-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('1aead74e-009d-5362-a700-6adeddae6297'::uuid, '8de3efc0-a3f4-5cab-b9e2-1b9ec58daa90'::uuid, 'Quelle convention fixe aujourd’hui le droit de la mer ?', 'mcq', '["La convention de Montego Bay (1982)","Le traité de Versailles (1919)","La convention de Genève (1949)","Le protocole de Kyoto (1997)"]'::jsonb, 0, 'Signée en 1982, elle entre en vigueur en 1994 et découpe l’espace maritime en zones.', 1),
    ('bd2edc97-e829-582c-90ef-af642cc46235'::uuid, '8de3efc0-a3f4-5cab-b9e2-1b9ec58daa90'::uuid, 'Quelle est la largeur de la zone économique exclusive (ZEE) ?', 'mcq', '["200 milles marins","12 milles marins","50 milles marins","500 milles marins"]'::jsonb, 0, 'L’État y détient des droits exclusifs d’exploitation, mais pas la souveraineté pleine.', 2),
    ('cdeb2638-6b0e-5c48-b77c-b6a042e2bebd'::uuid, '8de3efc0-a3f4-5cab-b9e2-1b9ec58daa90'::uuid, 'À quelle altitude commence conventionnellement l’espace ?', 'mcq', '["100 km","10 km","1 000 km","36 000 km"]'::jsonb, 0, 'C’est la ligne de Kármán ; 36 000 km est l’altitude de l’orbite géostationnaire.', 3),
    ('f6f65361-95e1-57fa-9193-5957614a7c14'::uuid, '8de3efc0-a3f4-5cab-b9e2-1b9ec58daa90'::uuid, 'Le traité de l’espace de 1967 interdit toute appropriation nationale de l’espace et des corps célestes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’espace y est déclaré « apanage de l’humanité tout entière ».', 4),
    ('9c0e6a48-32e7-5868-95c4-44654ed6798a'::uuid, '8de3efc0-a3f4-5cab-b9e2-1b9ec58daa90'::uuid, 'Par quoi transite l’essentiel des données numériques mondiales ?', 'mcq', '["Les câbles sous-marins","Les satellites géostationnaires","Les relais hertziens terrestres","Les réseaux mobiles"]'::jsonb, 0, 'Environ 99 % du trafic : d’où la vulnérabilité stratégique de ces câbles.', 5),
    ('b92ce383-97ac-57ab-8420-9ddf69f4e5f3'::uuid, '8de3efc0-a3f4-5cab-b9e2-1b9ec58daa90'::uuid, 'Que sont les nodules polymétalliques ?', 'mcq', '["Des concrétions minérales des grands fonds riches en métaux","Des réserves de gaz sous-marines","Des récifs coralliens artificiels","Des déchets industriels immergés"]'::jsonb, 0, 'Nickel, cobalt, manganèse : leur exploitation est encadrée par l’Autorité internationale des fonds marins.', 6),
    ('416f9298-3ea4-57a7-af4c-644cc22a259b'::uuid, '8de3efc0-a3f4-5cab-b9e2-1b9ec58daa90'::uuid, 'Quelle est la largeur de la mer territoriale, où l’État exerce sa pleine souveraineté ?', 'mcq', '["12 milles marins","200 milles marins","24 milles marins","3 milles marins"]'::jsonb, 0, 'Au-delà s’ouvre la zone contiguë, puis la ZEE.', 7),
    ('777ed432-5fa4-5613-a956-af9c16c8d698'::uuid, '8de3efc0-a3f4-5cab-b9e2-1b9ec58daa90'::uuid, 'La haute mer appartient à l’État côtier le plus proche.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est libre : nul ne peut se l’approprier, et ses grands fonds sont « patrimoine commun de l’humanité ».', 8),
    ('ec1949ea-8f30-5281-982b-535805e06d9a'::uuid, '1e482087-f1a8-5b3f-bbd6-a3aba587b006'::uuid, 'Quel satellite ouvre la conquête spatiale en 1957 ?', 'mcq', '["Spoutnik","Explorer 1","Vostok 1","Telstar"]'::jsonb, 0, 'Le « choc du Spoutnik » soviétique pousse les États-Unis à créer la NASA en 1958.', 1),
    ('f632acdd-711d-5041-944d-4012927111f2'::uuid, '1e482087-f1a8-5b3f-bbd6-a3aba587b006'::uuid, 'En quelle année a lieu le premier pas de l’homme sur la Lune ?', 'mcq', '["1969","1961","1975","1957"]'::jsonb, 0, 'Apollo 11, aboutissement de l’engagement pris par Kennedy en 1962.', 2),
    ('f66ab1ab-a3c3-5613-a6eb-ddc6d7c1e7b3'::uuid, '1e482087-f1a8-5b3f-bbd6-a3aba587b006'::uuid, 'Quelle mission symbolise la coopération spatiale de la détente, en 1975 ?', 'mcq', '["Apollo-Soyouz","Apollo 13","Vostok 6","Mir"]'::jsonb, 0, 'Un amarrage américano-soviétique en orbite, en pleine détente.', 3),
    ('87a6ccd8-d5f5-5925-928f-8c039aa3aa92'::uuid, '1e482087-f1a8-5b3f-bbd6-a3aba587b006'::uuid, 'Quelle station spatiale la Chine a-t-elle construite pour son propre compte ?', 'mcq', '["Tiangong","Mir","Skylab","Salyout"]'::jsonb, 0, 'Écartée de l’ISS, la Chine s’est dotée de sa propre station.', 4),
    ('acd9011c-03f2-59e8-93a1-538820276b4d'::uuid, '1e482087-f1a8-5b3f-bbd6-a3aba587b006'::uuid, 'Qu’est-ce qui explique la chute du coût de l’accès à l’orbite depuis les années 2010 ?', 'mcq', '["Les lanceurs réutilisables","L’abandon des satellites","La fin des programmes militaires","Le passage aux ballons stratosphériques"]'::jsonb, 0, 'C’est le pari technique de SpaceX, cœur du « New Space ».', 5),
    ('afe2ef5d-19d6-5404-b21b-fd484f15d1fe'::uuid, '1e482087-f1a8-5b3f-bbd6-a3aba587b006'::uuid, 'La conquête spatiale est restée un domaine exclusivement étatique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le New Space fait des entreprises privées des acteurs majeurs de l’accès à l’espace.', 6),
    ('ad40fbf2-2fb0-51a0-936c-d848a1cb4a02'::uuid, '1e482087-f1a8-5b3f-bbd6-a3aba587b006'::uuid, 'Quelle organisation donne à l’Europe un accès autonome à l’espace ?', 'mcq', '["L’Agence spatiale européenne","La NASA","L’OTAN","L’Union internationale des télécommunications"]'::jsonb, 0, 'Créée en 1975, elle exploite les lanceurs Ariane depuis Kourou.', 7),
    ('bcb81e90-61a2-543c-9d56-835e36dc84b9'::uuid, '1e482087-f1a8-5b3f-bbd6-a3aba587b006'::uuid, 'Quel risque croissant menace directement les satellites en orbite basse ?', 'mcq', '["Les débris spatiaux","Le seul rayonnement solaire","La raréfaction des fréquences","La hausse du niveau des mers"]'::jsonb, 0, 'Les essais antisatellites et les constellations multiplient les objets en orbite.', 8),
    ('90383442-6250-53fb-961c-a2bda7517904'::uuid, '5f251f98-88af-5744-854e-10986037ab43'::uuid, 'Quel pays détient la deuxième zone économique exclusive du monde ?', 'mcq', '["La France","Le Royaume-Uni","La Chine","Le Japon"]'::jsonb, 0, 'Près de 11 millions de km², grâce aux territoires ultramarins.', 1),
    ('36ed97fb-b69e-53a4-b100-7aa919203316'::uuid, '5f251f98-88af-5744-854e-10986037ab43'::uuid, 'Quelle zone maritime la Chine revendique-t-elle par sa « ligne en neuf traits » ?', 'mcq', '["La mer de Chine méridionale","La mer d’Okhotsk","Le golfe du Bengale","La mer Rouge"]'::jsonb, 0, 'Une revendication portant sur 80 à 90 % de la zone, contestée par ses voisins.', 2),
    ('e120998c-0904-5a17-9231-e1df6734992a'::uuid, '5f251f98-88af-5744-854e-10986037ab43'::uuid, 'Qu’a décidé la Cour permanente d’arbitrage en 2016 au sujet de la mer de Chine méridionale ?', 'mcq', '["Elle a donné tort aux revendications chinoises","Elle a validé la ligne en neuf traits","Elle a partagé la zone en deux","Elle s’est déclarée incompétente"]'::jsonb, 0, 'Pékin refuse d’appliquer la sentence : le droit ne vaut que si les États s’y plient.', 3),
    ('ec3b8068-7719-5584-9446-bd99f5f7f020'::uuid, '5f251f98-88af-5744-854e-10986037ab43'::uuid, 'Qu’est-ce qu’une opération FONOP menée par la marine américaine ?', 'mcq', '["Une patrouille affirmant la liberté de navigation","Une opération humanitaire","Un exercice de lutte anti-pollution","Une mission de cartographie"]'::jsonb, 0, 'Elle conteste par la présence les revendications maritimes jugées excessives.', 4),
    ('7f8cdb5f-70e6-56d9-9110-e7d9cfc85e23'::uuid, '5f251f98-88af-5744-854e-10986037ab43'::uuid, 'Pourquoi l’Arctique devient-il un espace de rivalités ?', 'mcq', '["La fonte de la banquise ouvre des routes et l’accès aux hydrocarbures","Sa population augmente rapidement","Il échappe à tout droit international","Il concentre la pêche mondiale"]'::jsonb, 0, 'Russie, Canada et Danemark y revendiquent l’extension de leur plateau continental.', 5),
    ('930abb43-47af-5541-ac0a-146bda47a42b'::uuid, '5f251f98-88af-5744-854e-10986037ab43'::uuid, 'La puissance maritime d’un État se mesure uniquement à sa flotte de guerre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Flotte de commerce, ports, compagnies et étendue de la ZEE comptent tout autant.', 6),
    ('03c16644-8acd-5d8b-8c0c-74fef59a7fea'::uuid, '5f251f98-88af-5744-854e-10986037ab43'::uuid, 'Quelle région concentre aujourd’hui l’essentiel de la piraterie maritime en Afrique de l’Ouest ?', 'mcq', '["Le golfe de Guinée","La mer Méditerranée","La mer Baltique","La mer Noire"]'::jsonb, 0, 'Avec le golfe d’Aden à l’est, c’est l’une des zones les plus exposées.', 7),
    ('d62ebd16-3a88-5219-b29c-83aa55566674'::uuid, '5f251f98-88af-5744-854e-10986037ab43'::uuid, 'Quelle part du commerce mondial, en volume, passe par la mer ?', 'mcq', '["Environ 80 %","Environ 20 %","Environ 50 %","Moins de 10 %"]'::jsonb, 0, 'D’où l’importance stratégique des détroits comme Malacca ou Ormuz.', 8),
    ('bd6ee636-068e-54bb-9750-77ed1971f881'::uuid, '2c9de8f0-9ee5-55a1-b923-c70d8a1beb41'::uuid, 'Quel horizon Xi Jinping fixe-t-il au « rêve chinois » de renouveau national ?', 'mcq', '["2049, centenaire de la République populaire","2030","2100","2025"]'::jsonb, 0, 'La date structure les grands programmes chinois, maritimes comme spatiaux.', 1),
    ('f9112268-64e9-558f-a9ba-ec094f68c0e6'::uuid, '2c9de8f0-9ee5-55a1-b923-c70d8a1beb41'::uuid, 'En quelle année la Chine réalise-t-elle son premier vol habité ?', 'mcq', '["2003","1992","2013","2019"]'::jsonb, 0, 'Elle devient la troisième puissance à envoyer seule un homme dans l’espace.', 2),
    ('c233765b-ced1-5531-b6c7-aaf7cbfee79d'::uuid, '2c9de8f0-9ee5-55a1-b923-c70d8a1beb41'::uuid, 'Quel système de navigation par satellites la Chine a-t-elle déployé face au GPS ?', 'mcq', '["Beidou","Galileo","Glonass","Starlink"]'::jsonb, 0, 'Galileo est européen, Glonass russe : chaque puissance veut son autonomie.', 3),
    ('4afa00c8-1dd7-5b25-969e-1ff107831204'::uuid, '2c9de8f0-9ee5-55a1-b923-c70d8a1beb41'::uuid, 'Où la Chine a-t-elle ouvert sa première base militaire à l’étranger, en 2017 ?', 'mcq', '["À Djibouti","Au Pirée","À Gwadar","À Hambantota"]'::jsonb, 0, 'Sur la route stratégique de Bab el-Mandeb, verrou de la mer Rouge.', 4),
    ('a13df231-079a-5232-a5b2-b2833bca2b13'::uuid, '2c9de8f0-9ee5-55a1-b923-c70d8a1beb41'::uuid, 'Qu’appelle-t-on le « dilemme de Malacca » ?', 'mcq', '["La dépendance chinoise à un détroit qu’elle ne contrôle pas","Un conflit frontalier avec la Malaisie","Un litige sur la pêche","Une querelle de souveraineté avec l’Indonésie"]'::jsonb, 0, 'L’essentiel des hydrocarbures chinois y transite, sous surveillance américaine.', 5),
    ('0c27f6dc-12f5-5257-943c-4234013c688e'::uuid, '2c9de8f0-9ee5-55a1-b923-c70d8a1beb41'::uuid, 'La Chine participe à la Station spatiale internationale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Écartée du programme, elle a construit sa propre station, Tiangong.', 6),
    ('a263eaca-fd81-581a-acbf-ef1b349787fa'::uuid, '2c9de8f0-9ee5-55a1-b923-c70d8a1beb41'::uuid, 'Quel volet des nouvelles routes de la soie concerne les mers ?', 'mcq', '["Les investissements dans les ports étrangers","Les voies ferrées transcontinentales","Le financement de barrages","Les échanges universitaires"]'::jsonb, 0, 'Pirée, Gwadar, Hambantota : une chaîne de ports jalonne la route maritime.', 7),
    ('04cae6f3-f7b9-5e2e-96e9-ab7ab2a4ebcc'::uuid, '2c9de8f0-9ee5-55a1-b923-c70d8a1beb41'::uuid, 'Quelle réaction la montée en puissance chinoise a-t-elle provoquée dans l’Indo-Pacifique ?', 'mcq', '["Le rapprochement de ses voisins avec les États-Unis (Quad, AUKUS)","Un désengagement américain de la région","La dissolution de l’ASEAN","Un accord de partage de la mer de Chine"]'::jsonb, 0, 'La puissance suscite des contre-alliances : c’est un classique des relations internationales.', 8),
    ('49934b46-b6b2-5cce-8661-b1ae4aba3989'::uuid, 'e99c1cb9-6b7c-5041-9d29-f825459f7e36'::uuid, 'Pour Clausewitz, la guerre est…', 'mcq', '["la continuation de la politique par d’autres moyens","un accident de l’histoire","un phénomène purement économique","une maladie des sociétés"]'::jsonb, 0, 'Elle est un instrument au service d’une fin politique, pas une fin en soi.', 1),
    ('6c7d258a-f4fa-54a9-a15f-69f2cb13e5d6'::uuid, 'e99c1cb9-6b7c-5041-9d29-f825459f7e36'::uuid, 'Qu’est-ce qu’une paix négative ?', 'mcq', '["La simple absence de guerre, sans règlement du différend","Une paix imposée par un vainqueur","Une paix accompagnée de réparations","Une paix garantie par l’ONU"]'::jsonb, 0, 'Par opposition à la paix positive, qui suppose justice et réconciliation.', 2),
    ('58866a24-eee0-52a8-8495-1b8bc37bfab0'::uuid, 'e99c1cb9-6b7c-5041-9d29-f825459f7e36'::uuid, 'Depuis 1945, quelle forme de conflit domine ?', 'mcq', '["Les conflits intra-étatiques","Les guerres déclarées entre États","Les guerres coloniales","Les guerres de succession dynastique"]'::jsonb, 0, 'Guerres civiles, guérillas et insurrections l’emportent sur la guerre classique.', 3),
    ('ea7cddfd-63db-5f2a-9a75-42158803b60e'::uuid, 'e99c1cb9-6b7c-5041-9d29-f825459f7e36'::uuid, 'Qu’appelle-t-on un conflit asymétrique ?', 'mcq', '["Une armée régulière face à un adversaire irrégulier","Un conflit entre deux armées de taille égale","Un conflit sans victimes civiles","Une guerre menée uniquement par des drones"]'::jsonb, 0, 'La disproportion des moyens y change les formes de combat.', 4),
    ('074d76cd-0f3a-51c5-b46a-88e2e16ad30f'::uuid, 'e99c1cb9-6b7c-5041-9d29-f825459f7e36'::uuid, 'Quel philosophe pose en 1795 le projet d’une paix perpétuelle entre États ?', 'mcq', '["Kant","Machiavel","Hobbes","Rousseau"]'::jsonb, 0, 'Son projet de fédération d’États républicains inspire la SDN puis l’ONU.', 5),
    ('9d4764c5-197f-5241-8759-4737292d817f'::uuid, 'e99c1cb9-6b7c-5041-9d29-f825459f7e36'::uuid, 'Un conflit gelé signifie que le différend a été réglé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les armes se taisent, mais le désaccord demeure : Chypre, la Corée, le Cachemire.', 6),
    ('0cf62e36-f0c0-5720-bee3-c4ea286a308c'::uuid, 'e99c1cb9-6b7c-5041-9d29-f825459f7e36'::uuid, 'Qui a forgé la distinction entre paix négative et paix positive ?', 'mcq', '["Johan Galtung","Clausewitz","Mary Kaldor","Raymond Aron"]'::jsonb, 0, 'Le fondateur des études sur la paix, dans les années 1960.', 7),
    ('3b026366-5029-50b9-a4eb-4fdd3808b3a7'::uuid, 'e99c1cb9-6b7c-5041-9d29-f825459f7e36'::uuid, 'Quelle est la principale victime des conflits contemporains ?', 'mcq', '["Les populations civiles","Les armées régulières","Les forces de maintien de la paix","Les sociétés militaires privées"]'::jsonb, 0, 'C’est l’un des traits majeurs des « nouvelles guerres ».', 8),
    ('4248cc84-5030-5743-a2fb-7cdc3acf1cc3'::uuid, '52c5fe34-98cb-5d4f-a2d8-3bf4e4178e5e'::uuid, 'Quels traités mettent fin à la guerre de Trente Ans en 1648 ?', 'mcq', '["Les traités de Westphalie","Le traité de Versailles","Le traité d’Utrecht","Le congrès de Vienne"]'::jsonb, 0, 'Ils fondent le système des États souverains.', 1),
    ('2f37dc32-f185-5c40-ba27-51af0a70d1c0'::uuid, '52c5fe34-98cb-5d4f-a2d8-3bf4e4178e5e'::uuid, 'Qu’instaure le système westphalien ?', 'mcq', '["La souveraineté des États sur leur territoire","Un gouvernement mondial","La liberté religieuse universelle","L’interdiction de la guerre"]'::jsonb, 0, 'Chaque État est maître chez lui : c’est la matrice du droit international moderne.', 2),
    ('2071291f-0f73-56a5-9c55-1fd235578683'::uuid, '52c5fe34-98cb-5d4f-a2d8-3bf4e4178e5e'::uuid, 'Qu’est-ce qu’une guerre hybride ?', 'mcq', '["Un conflit mêlant forces régulières, milices, cyberattaques et désinformation","Une guerre entre deux coalitions","Une guerre limitée à la mer","Un conflit arbitré par l’ONU"]'::jsonb, 0, 'La Crimée en 2014 en est le cas d’école : agression sans déclaration.', 3),
    ('41f2fef6-166c-5255-a598-f6a3491f7a93'::uuid, '52c5fe34-98cb-5d4f-a2d8-3bf4e4178e5e'::uuid, 'Quel attentat marque l’entrée du terrorisme djihadiste dans l’agenda mondial ?', 'mcq', '["Le 11 septembre 2001","L’attentat de Munich en 1972","Les attentats de Madrid en 2004","L’attentat d’Oklahoma City"]'::jsonb, 0, 'Il déclenche la « guerre contre le terrorisme » et l’intervention en Afghanistan.', 4),
    ('e4f04d48-d87a-593a-a58d-2f6a7adbbe8e'::uuid, '52c5fe34-98cb-5d4f-a2d8-3bf4e4178e5e'::uuid, 'Quel virus informatique a visé le programme nucléaire iranien ?', 'mcq', '["Stuxnet","WannaCry","NotPetya","Mirai"]'::jsonb, 0, 'Une cyberattaque produisant un effet physique : les centrifugeuses en ont été détruites.', 5),
    ('c931e09a-bc2b-5d8b-b2e4-abab92db1ec6'::uuid, '52c5fe34-98cb-5d4f-a2d8-3bf4e4178e5e'::uuid, 'Les guerres interétatiques de haute intensité ont totalement disparu depuis 1945.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’invasion de l’Ukraine en 2022 en administre la preuve inverse.', 6),
    ('5e02327f-eb5d-50ff-9021-2ec4e7cf2564'::uuid, '52c5fe34-98cb-5d4f-a2d8-3bf4e4178e5e'::uuid, 'Qu’est-ce que la guerre totale ?', 'mcq', '["Une guerre mobilisant l’ensemble des ressources et des populations","Une guerre menée sur tous les continents","Une guerre sans prisonniers","Une guerre menée sans alliés"]'::jsonb, 0, 'Économie, science et sociétés entières sont mises au service du front.', 7),
    ('4f6908cc-68d0-542d-a523-8faff7b5c59d'::uuid, '52c5fe34-98cb-5d4f-a2d8-3bf4e4178e5e'::uuid, 'Quel acteur privé russe illustre le recours aux mercenaires dans les conflits récents ?', 'mcq', '["Le groupe Wagner","Blackwater","La Légion étrangère","Les Casques bleus"]'::jsonb, 0, 'Sociétés militaires privées et milices brouillent la responsabilité des États.', 8),
    ('2b938a8e-93cf-5c18-9389-ce1f2c1204e0'::uuid, 'ac8a45f1-36a4-50e6-b805-36283b416404'::uuid, 'Quel congrès réorganise l’Europe après la chute de Napoléon ?', 'mcq', '["Le congrès de Vienne (1814-1815)","Le congrès de Berlin (1878)","La conférence de Yalta","La conférence de Bandung"]'::jsonb, 0, 'Il instaure un équilibre entre grandes puissances, le « concert européen ».', 1),
    ('d96b2822-fd44-5c0a-856e-98f9f1688852'::uuid, 'ac8a45f1-36a4-50e6-b805-36283b416404'::uuid, 'Quel président américain est à l’origine de la Société des Nations ?', 'mcq', '["Wilson","Roosevelt","Truman","Taft"]'::jsonb, 0, 'Paradoxe fameux : le Sénat américain refuse ensuite d’y adhérer.', 2),
    ('3e17cc43-2bcc-5177-b751-43b2d7a6332f'::uuid, 'ac8a45f1-36a4-50e6-b805-36283b416404'::uuid, 'Quelle faiblesse majeure explique l’échec de la SDN ?', 'mcq', '["L’absence des États-Unis et de moyens de contrainte","Un budget trop important","Un siège mal situé","Le trop grand nombre de membres"]'::jsonb, 0, 'Sans armée ni unanimité possible, elle ne peut faire respecter ses décisions.', 3),
    ('334c18b2-9f0c-5ead-924c-e416eb10b8f8'::uuid, 'ac8a45f1-36a4-50e6-b805-36283b416404'::uuid, 'Combien d’États disposent du droit de veto au Conseil de sécurité de l’ONU ?', 'mcq', '["5","3","10","15"]'::jsonb, 0, 'États-Unis, Russie, Chine, France, Royaume-Uni : les vainqueurs de 1945.', 4),
    ('71463598-7a2e-57a7-a78b-c30071e21efc'::uuid, 'ac8a45f1-36a4-50e6-b805-36283b416404'::uuid, 'Quelle juridiction juge les individus pour crimes contre l’humanité depuis 2002 ?', 'mcq', '["La Cour pénale internationale","La Cour internationale de justice","La Cour européenne des droits de l’homme","Le Conseil de sécurité"]'::jsonb, 0, 'La CIJ, elle, tranche les différends entre États, pas entre personnes.', 5),
    ('a73316fc-57a1-53ee-b1e0-de8e3cf8746f'::uuid, 'ac8a45f1-36a4-50e6-b805-36283b416404'::uuid, 'La Charte de l’ONU autorise le recours à la force dans tous les cas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seulement en légitime défense ou sur décision du Conseil de sécurité.', 6),
    ('1d969910-d483-5681-84d8-2ffbbf5f0879'::uuid, 'ac8a45f1-36a4-50e6-b805-36283b416404'::uuid, 'Comment appelle-t-on les forces déployées par l’ONU dans les opérations de maintien de la paix ?', 'mcq', '["Les Casques bleus","Les Bérets verts","La Force de réaction rapide","La Légion internationale"]'::jsonb, 0, 'Elles s’interposent, mais n’ont qu’un mandat limité et des règles d’engagement strictes.', 7),
    ('8786a6b9-8e65-5bdd-a908-9bd9b00f6a61'::uuid, 'ac8a45f1-36a4-50e6-b805-36283b416404'::uuid, 'Quel principe fondamental le système westphalien lègue-t-il à la diplomatie moderne ?', 'mcq', '["La souveraineté des États","Le droit d’ingérence","La sécurité collective","Le désarmement général"]'::jsonb, 0, 'Tout le droit international s’est construit à partir de ce principe — et contre ses excès.', 8),
    ('159248c5-e348-55bf-8c5e-adcdf0a522a9'::uuid, '825749e6-5451-54e8-9f82-48785dfeaa8d'::uuid, 'Quels accords secrets de 1916 préparent le partage du Moyen-Orient entre la France et le Royaume-Uni ?', 'mcq', '["Les accords Sykes-Picot","Les accords de Camp David","Les accords d’Oslo","Le pacte de Bagdad"]'::jsonb, 0, 'Ils dessinent des frontières décidées hors de la région.', 1),
    ('491af9c3-98a9-526b-8057-a66f9d0e3c5f'::uuid, '825749e6-5451-54e8-9f82-48785dfeaa8d'::uuid, 'En quelle année l’État d’Israël est-il proclamé ?', 'mcq', '["1948","1917","1967","1993"]'::jsonb, 0, 'La proclamation suit le plan de partage de l’ONU de 1947.', 2),
    ('cc0a187d-297b-5d29-9a85-decf014134a7'::uuid, '825749e6-5451-54e8-9f82-48785dfeaa8d'::uuid, 'Que promet la déclaration Balfour de 1917 ?', 'mcq', '["Un foyer national juif en Palestine","L’indépendance de la Syrie","Un État kurde","La fin des mandats"]'::jsonb, 0, 'Elle engage le Royaume-Uni et pèse sur tout le siècle qui suit.', 3),
    ('88f56630-1a24-506e-9bef-574721e87ad1'::uuid, '825749e6-5451-54e8-9f82-48785dfeaa8d'::uuid, 'Quelle guerre conduit Israël à occuper la Cisjordanie, Gaza et le Golan ?', 'mcq', '["La guerre des Six Jours (1967)","La guerre du Kippour (1973)","La guerre de 1948","La guerre du Liban"]'::jsonb, 0, 'L’occupation issue de 1967 reste au cœur du conflit.', 4),
    ('8786a058-118a-561f-b300-8fad17b8f9ba'::uuid, '825749e6-5451-54e8-9f82-48785dfeaa8d'::uuid, 'Que prévoient les accords d’Oslo de 1993 ?', 'mcq', '["Une reconnaissance mutuelle et une autonomie palestinienne","La création immédiate d’un État palestinien","Le retrait israélien du Golan","Une union douanière régionale"]'::jsonb, 0, 'Le processus s’enraye ensuite, faute d’application et sous l’effet de la colonisation.', 5),
    ('fc67d3f4-5384-5c22-ad11-c0b3da371f47'::uuid, '825749e6-5451-54e8-9f82-48785dfeaa8d'::uuid, 'Quelle rivalité régionale structure de nombreux conflits actuels du Moyen-Orient ?', 'mcq', '["Arabie saoudite / Iran","Turquie / Égypte","Israël / Jordanie","Irak / Koweït"]'::jsonb, 0, 'Elle se rejoue par procuration au Yémen, en Syrie, au Liban.', 6),
    ('e3bf5cd1-d5d2-5cbc-84d6-43d4210d523c'::uuid, '825749e6-5451-54e8-9f82-48785dfeaa8d'::uuid, 'Le détroit d’Ormuz est un point de passage stratégique pour les hydrocarbures.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une part majeure du pétrole mondial y transite : le fermer serait une arme.', 7),
    ('ae04881c-cc13-5c6f-bf20-bb728b23d69f'::uuid, '825749e6-5451-54e8-9f82-48785dfeaa8d'::uuid, 'Quelle guerre oppose deux États de la région entre 1980 et 1988 ?', 'mcq', '["La guerre Iran-Irak","La guerre du Golfe","La guerre du Kippour","La guerre civile libanaise"]'::jsonb, 0, 'Huit ans de conflit, avec emploi d’armes chimiques et centaines de milliers de morts.', 8),
    ('35890c48-105c-531d-b22e-6de9ac4e3c43'::uuid, 'cf1affe7-109c-5c06-af40-683d32a4afa0'::uuid, 'Quelle est la différence essentielle entre histoire et mémoire ?', 'mcq', '["L’histoire est un savoir critique, la mémoire un souvenir vécu et sélectif","La mémoire est écrite, l’histoire est orale","L’histoire est officielle, la mémoire est privée","Il n’y a aucune différence"]'::jsonb, 0, 'L’une se discute et se démontre, l’autre se transmet et s’éprouve.', 1),
    ('e8e60add-a332-52e1-8b1a-631f82cb988b'::uuid, 'cf1affe7-109c-5c06-af40-683d32a4afa0'::uuid, 'En quelle année la France reconnaît-elle officiellement le terme de « guerre d’Algérie » ?', 'mcq', '["1999","1962","1982","2012"]'::jsonb, 0, 'Jusque-là, on parlait d’« événements » ou d’« opérations de maintien de l’ordre ».', 2),
    ('e04557af-3211-5578-90ff-b29a6d25a2be'::uuid, 'cf1affe7-109c-5c06-af40-683d32a4afa0'::uuid, 'Quel événement de 1961 a longtemps été occulté en France ?', 'mcq', '["La répression de la manifestation algérienne du 17 octobre à Paris","Le putsch d’Alger","La bataille d’Alger","Les accords d’Évian"]'::jsonb, 0, 'Une plaque commémorative n’a été posée qu’en 2001.', 3),
    ('899168e8-3989-56a0-941d-c24e6e69f69d'::uuid, 'cf1affe7-109c-5c06-af40-683d32a4afa0'::uuid, 'Qui sont les harkis ?', 'mcq', '["Des supplétifs algériens engagés aux côtés de l’armée française","Les combattants du FLN","Les colons français d’Algérie","Les appelés du contingent"]'::jsonb, 0, 'Abandonnés en 1962, leur reconnaissance a été très tardive.', 4),
    ('d0c17c8b-69cb-51c5-94c0-2a69029ee179'::uuid, 'cf1affe7-109c-5c06-af40-683d32a4afa0'::uuid, 'Quel effet ont eu les lois d’amnistie qui suivent les accords d’Évian ?', 'mcq', '["Elles interdisent les poursuites et referment le dossier","Elles ouvrent les archives","Elles indemnisent les victimes","Elles créent une commission vérité"]'::jsonb, 0, 'L’oubli organisé a longtemps empêché le travail de mémoire.', 5),
    ('98a20e0c-a70f-51de-b4d8-2912075f3488'::uuid, 'cf1affe7-109c-5c06-af40-683d32a4afa0'::uuid, 'Quel historien a structuré le champ des travaux sur la mémoire de la guerre d’Algérie ?', 'mcq', '["Benjamin Stora","Robert Paxton","Henry Rousso","Pierre Nora"]'::jsonb, 0, 'Son rapport de 2021 propose des gestes de réconciliation mémorielle.', 6),
    ('6ea4f209-77cd-5abe-883a-79ef5ba4b06d'::uuid, 'cf1affe7-109c-5c06-af40-683d32a4afa0'::uuid, 'Les pieds-noirs et les harkis partagent la même mémoire de la guerre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chaque groupe porte une mémoire distincte, parfois concurrente des autres.', 7),
    ('331212b6-bf5c-5781-9d29-366c188981d4'::uuid, 'cf1affe7-109c-5c06-af40-683d32a4afa0'::uuid, 'Qu’a reconnu l’État français en 2018 au sujet de Maurice Audin ?', 'mcq', '["Sa responsabilité dans son arrestation et sa mort","Son statut de héros national","Son engagement au FLN","Son innocence judiciaire"]'::jsonb, 0, 'Une reconnaissance qui vaut aussi pour le système de torture mis en place.', 8),
    ('23c6ea9f-8a53-5d5c-b1eb-08d7648cca12'::uuid, 'f8530816-38d2-5fc5-b2fc-69991283b456'::uuid, 'Que dispose l’article 231 du traité de Versailles ?', 'mcq', '["Il désigne l’Allemagne et ses alliés comme responsables des dommages","Il crée la Société des Nations","Il fixe les frontières de la Pologne","Il interdit l’armée allemande"]'::jsonb, 0, 'C’est la « clause de culpabilité », fondement juridique des réparations.', 1),
    ('5d5a1b9c-482b-5370-b118-829937502e24'::uuid, 'f8530816-38d2-5fc5-b2fc-69991283b456'::uuid, 'Quel effet cette clause a-t-elle eu en Allemagne ?', 'mcq', '["Elle a nourri le sentiment d’un Diktat exploité par les nationalistes","Elle a été acceptée sans débat","Elle a provoqué une révolution","Elle a été annulée dès 1920"]'::jsonb, 0, 'Le ressentiment de Versailles est un ressort de la propagande nazie.', 2),
    ('787e3fe0-d8a0-5641-920c-d064de9f0b77'::uuid, 'f8530816-38d2-5fc5-b2fc-69991283b456'::uuid, 'Quel historien allemand rouvre en 1961 la question des buts de guerre allemands ?', 'mcq', '["Fritz Fischer","Christopher Clark","Ernst Nolte","Hannah Arendt"]'::jsonb, 0, 'Sa thèse fait scandale car elle vient d’Allemagne même.', 3),
    ('968c3e32-e182-5bee-aded-e46a3c54b5b1'::uuid, 'f8530816-38d2-5fc5-b2fc-69991283b456'::uuid, 'Comment les historiens actuels caractérisent-ils souvent le déclenchement de 1914 ?', 'mcq', '["Comme un engrenage d’alliances, d’armements et de plans rigides","Comme un accident sans cause","Comme le fruit d’un complot unique","Comme une décision de la SDN"]'::jsonb, 0, 'Christopher Clark parle de dirigeants « somnambules ».', 4),
    ('9ebd7f42-bf30-5da9-aa70-d243e9b1ce85'::uuid, 'f8530816-38d2-5fc5-b2fc-69991283b456'::uuid, 'Pourquoi les États ont-ils publié des recueils de documents diplomatiques dans les années 1920 ?', 'mcq', '["Pour peser sur le débat sur les responsabilités","Pour former les étudiants","Pour respecter une obligation du traité","Pour préparer la SDN"]'::jsonb, 0, 'L’écriture de l’histoire devient un instrument de politique étrangère.', 5),
    ('17f013c1-1475-58ca-8e70-deea7027d904'::uuid, 'f8530816-38d2-5fc5-b2fc-69991283b456'::uuid, 'Le débat sur les responsabilités de 1914 a été tranché définitivement en 1919.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il a été rouvert dans les années 1960 et se poursuit aujourd’hui.', 6),
    ('83f052ce-7eac-55f2-84ea-be8ff8d2a7fc'::uuid, 'f8530816-38d2-5fc5-b2fc-69991283b456'::uuid, 'Quel plan militaire allemand illustre la rigidité des mobilisations de 1914 ?', 'mcq', '["Le plan Schlieffen","Le plan XVII","Le plan Dawes","Le plan Marshall"]'::jsonb, 0, 'Une fois lancée, la mécanique de mobilisation laissait peu de place à la diplomatie.', 7),
    ('b64bd3b3-7f2f-50a4-96b9-05937867f679'::uuid, 'f8530816-38d2-5fc5-b2fc-69991283b456'::uuid, 'Que montre ce jalon sur le travail de l’historien ?', 'mcq', '["Les interprétations évoluent avec les sources et la méthode","L’histoire ne change jamais","Toutes les interprétations se valent","L’histoire dépend des seuls témoignages"]'::jsonb, 0, 'Plusieurs lectures existent, mais elles se jugent aux archives et à la démonstration.', 8),
    ('27228da4-df1e-5c98-9aab-61ddd196e935'::uuid, '36a455b4-2101-58f1-91af-89dc88f64395'::uuid, 'Quel génocide a lieu au Rwanda en 1994 ?', 'mcq', '["Le génocide des Tutsi","Le génocide des Hutu","Le génocide des Twa","Le génocide des Bantous"]'::jsonb, 0, 'Environ 800 000 morts en cent jours, planifiés par le pouvoir en place.', 1),
    ('042cec4e-e0e9-51f7-9c64-25a012e0c6b0'::uuid, '36a455b4-2101-58f1-91af-89dc88f64395'::uuid, 'Quel massacre de juillet 1995 a été qualifié de génocide par la justice internationale ?', 'mcq', '["Srebrenica","Vukovar","Mostar","Pristina"]'::jsonb, 0, 'Plus de 8 000 hommes et adolescents bosniaques musulmans y ont été tués.', 2),
    ('1727329b-0e02-584e-9b96-032e1e9bde37'::uuid, '36a455b4-2101-58f1-91af-89dc88f64395'::uuid, 'Que sont les gacaca ?', 'mcq', '["Des tribunaux communautaires rwandais jugeant les participants au génocide","Des commissions vérité sud-africaines","Des chambres du TPIR","Des mémoriaux du génocide"]'::jsonb, 0, 'Près de deux millions de dossiers traités entre 2002 et 2012.', 3),
    ('b05e1352-7045-59e1-ac1c-b189b616c88e'::uuid, '36a455b4-2101-58f1-91af-89dc88f64395'::uuid, 'Quel tribunal a forgé en 1945-1946 la notion de crime contre l’humanité ?', 'mcq', '["Le tribunal de Nuremberg","Le TPIY","La Cour internationale de justice","Le tribunal de Tokyo"]'::jsonb, 0, 'Les TPI des années 1990 en sont les héritiers directs.', 4),
    ('53b2b71a-f30d-5228-861d-e171f549bd36'::uuid, '36a455b4-2101-58f1-91af-89dc88f64395'::uuid, 'Qui a créé le TPIY et le TPIR ?', 'mcq', '["Le Conseil de sécurité de l’ONU","L’Union européenne","L’Assemblée générale de l’ONU","La Cour pénale internationale"]'::jsonb, 0, 'Des tribunaux ad hoc, créés pour un conflit et une période précis.', 5),
    ('15a7c868-98b0-58a0-be9f-dc6640681770'::uuid, '36a455b4-2101-58f1-91af-89dc88f64395'::uuid, 'La Cour pénale internationale a été créée pour juger un conflit précis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'À la différence des TPI ad hoc, elle est permanente et à vocation générale.', 6),
    ('c399f5cc-96a5-5679-b08b-80303ca93ab0'::uuid, '36a455b4-2101-58f1-91af-89dc88f64395'::uuid, 'Quelle critique majeure a été adressée aux juridictions gacaca ?', 'mcq', '["La faiblesse des garanties procédurales","Leur lenteur excessive","Leur coût pour l’ONU","Leur refus de juger les responsables"]'::jsonb, 0, 'Rapidité et proximité ont été obtenues au prix des droits de la défense.', 7),
    ('bfea0730-fd0d-57d2-bae0-22117ee87382'::uuid, '36a455b4-2101-58f1-91af-89dc88f64395'::uuid, 'Qu’a établi le rapport Duclert remis en 2021 ?', 'mcq', '["Les responsabilités accablantes de la France au Rwanda","La complicité de la Belgique","Le bilan exact du génocide","L’innocence de l’ONU"]'::jsonb, 0, 'Un travail d’historiens commandé par l’État, à partir des archives.', 8),
    ('23894615-09c9-57bc-b641-b22883118573'::uuid, '366118c6-c48a-51b8-9442-34bb26c49595'::uuid, 'Quel procès de 1961 relance la mémoire du génocide des Juifs dans le monde ?', 'mcq', '["Le procès Eichmann à Jérusalem","Le procès de Nuremberg","Le procès Barbie","Le procès Papon"]'::jsonb, 0, 'Sa médiatisation donne enfin la parole aux témoins.', 1),
    ('a5aec3b3-04be-552f-9af3-587b4aafa0dd'::uuid, '366118c6-c48a-51b8-9442-34bb26c49595'::uuid, 'Qu’appelle-t-on le résistancialisme ?', 'mcq', '["Le récit d’une France massivement résistante","Un courant de la Résistance","Une doctrine militaire","Un mouvement littéraire"]'::jsonb, 0, 'Il a longtemps occulté la collaboration et le sort des Juifs de France.', 2),
    ('60c06e6e-3d2c-5fb8-8f82-a64816ddc95f'::uuid, '366118c6-c48a-51b8-9442-34bb26c49595'::uuid, 'Quel historien américain a renouvelé en 1973 l’histoire du régime de Vichy ?', 'mcq', '["Robert Paxton","Raul Hilberg","Henry Rousso","Pierre Nora"]'::jsonb, 0, 'La France de Vichy montre une collaboration d’État, non une contrainte subie.', 3),
    ('cfb5a050-a21c-5bda-8da4-eb0996054aa2'::uuid, '366118c6-c48a-51b8-9442-34bb26c49595'::uuid, 'Quel président français reconnaît en 1995 la responsabilité de l’État dans la déportation ?', 'mcq', '["Jacques Chirac","François Mitterrand","Charles de Gaulle","Nicolas Sarkozy"]'::jsonb, 0, 'Son discours du Vél d’Hiv rompt avec la position de ses prédécesseurs.', 4),
    ('42a5e57a-e117-50eb-8168-a5c7fc3bd64c'::uuid, '366118c6-c48a-51b8-9442-34bb26c49595'::uuid, 'Comment nomme-t-on le génocide des Tsiganes ?', 'mcq', '["Le Porajmos","La Shoah","L’Aktion T4","Le Judenrat"]'::jsonb, 0, 'Entre 200 000 et 500 000 victimes, reconnues très tardivement.', 5),
    ('c4dde561-f888-5d32-b483-92131150565a'::uuid, '366118c6-c48a-51b8-9442-34bb26c49595'::uuid, 'Les crimes contre l’humanité sont imprescriptibles en droit français.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Depuis la loi de 1964 : c’est ce qui a rendu possibles les procès Barbie, Touvier et Papon.', 6),
    ('76be3383-7bc0-5663-8917-5baf214d90fd'::uuid, '366118c6-c48a-51b8-9442-34bb26c49595'::uuid, 'Quel film de 1985 recueille les témoignages de survivants, de bourreaux et de témoins ?', 'mcq', '["Shoah, de Claude Lanzmann","Nuit et brouillard","Le Chagrin et la Pitié","La Liste de Schindler"]'::jsonb, 0, 'Neuf heures de témoignages, sans aucune image d’archives.', 7),
    ('233d43eb-55ce-5d79-a23b-c1e8ec39f382'::uuid, '366118c6-c48a-51b8-9442-34bb26c49595'::uuid, 'Quel événement de juillet 1942 marque la participation de l’État français à la déportation ?', 'mcq', '["La rafle du Vél d’Hiv","Le statut des Juifs","La création de la Milice","Le procès de Riom"]'::jsonb, 0, 'Plus de 13 000 personnes arrêtées à Paris par la police française.', 8),
    ('9376551f-0f9d-5ebb-a1c7-3ffc2053c603'::uuid, '45a1a647-0842-5378-b258-0ad0dd124281'::uuid, 'Quel événement fait passer le patrimoine d’un bien privé à un bien de la nation ?', 'mcq', '["La Révolution française","La Renaissance","Le Second Empire","La Libération"]'::jsonb, 0, 'La nationalisation des biens du clergé et de la Couronne pose la question de leur conservation.', 1),
    ('36b90ef3-36ae-54a9-92ab-295dceea058f'::uuid, '45a1a647-0842-5378-b258-0ad0dd124281'::uuid, 'Qui popularise le mot « vandalisme » en 1794 ?', 'mcq', '["L’abbé Grégoire","Prosper Mérimée","Viollet-le-Duc","André Malraux"]'::jsonb, 0, 'Il dénonce les destructions révolutionnaires pour mieux défendre la conservation.', 2),
    ('213444cb-126b-58cd-a54e-e4ad6cdbbcf8'::uuid, '45a1a647-0842-5378-b258-0ad0dd124281'::uuid, 'Qui est nommé inspecteur général des Monuments historiques en 1834 ?', 'mcq', '["Prosper Mérimée","Viollet-le-Duc","Victor Hugo","Guizot"]'::jsonb, 0, 'Il parcourt la France pour recenser les édifices à sauver.', 3),
    ('21f2bbb3-be22-5e2e-aa30-7fe4bed629b4'::uuid, '45a1a647-0842-5378-b258-0ad0dd124281'::uuid, 'Quelle convention crée la liste du patrimoine mondial ?', 'mcq', '["La convention de l’UNESCO de 1972","La convention de La Haye de 1954","La convention de 2003","La convention de Faro"]'::jsonb, 0, 'Elle repose sur le critère de « valeur universelle exceptionnelle ».', 4),
    ('a873b49c-6834-54f8-8fb6-1e1fadc64343'::uuid, '45a1a647-0842-5378-b258-0ad0dd124281'::uuid, 'Quel sauvetage est considéré comme l’acte fondateur du patrimoine mondial ?', 'mcq', '["Les temples d’Abou Simbel","Le Mont-Saint-Michel","Angkor","Venise"]'::jsonb, 0, 'Déplacés pierre par pierre pour échapper à la montée des eaux du barrage d’Assouan.', 5),
    ('5d0fe438-3b6f-5edc-981a-006454612714'::uuid, '45a1a647-0842-5378-b258-0ad0dd124281'::uuid, 'Le patrimoine culturel immatériel est reconnu par l’UNESCO depuis 2003.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Savoir-faire, fêtes, langues et pratiques entrent alors dans le patrimoine.', 6),
    ('edbf330c-29c4-5839-9eaf-a2bea1fe58d7'::uuid, '45a1a647-0842-5378-b258-0ad0dd124281'::uuid, 'Quelle loi française organise le classement des monuments historiques ?', 'mcq', '["La loi de 1913","La loi de 1830","La loi de 1962","La loi de 2016"]'::jsonb, 0, 'Elle reste la base du droit du patrimoine en France.', 7),
    ('3f33b02e-0e14-5d8b-a6da-c2a1ba0192b4'::uuid, '45a1a647-0842-5378-b258-0ad0dd124281'::uuid, 'Comment la liste du patrimoine mondial est-elle répartie dans le monde ?', 'mcq', '["Très inégalement, au profit de l’Europe","De façon équilibrée entre continents","Au profit de l’Afrique","Selon la population des États"]'::jsonb, 0, 'La liste reflète aussi les moyens administratifs et diplomatiques des États.', 8),
    ('8757beea-282b-59a9-9917-57d836f7b975'::uuid, '878d212b-96cd-5b84-8064-d6a3093af5ab'::uuid, 'Quelle convention protège les biens culturels en cas de conflit armé ?', 'mcq', '["La convention de La Haye (1954)","La convention de 1972","La convention de 2003","La convention de Genève"]'::jsonb, 0, 'Adoptée après les destructions de la Seconde Guerre mondiale.', 1),
    ('7555f693-5425-555b-9045-abf830512b64'::uuid, '878d212b-96cd-5b84-8064-d6a3093af5ab'::uuid, 'Qu’a jugé la Cour pénale internationale en 2016 dans l’affaire al-Mahdi ?', 'mcq', '["La destruction des mausolées de Tombouctou comme crime de guerre","Un génocide au Mali","Un trafic d’antiquités","Une prise d’otages"]'::jsonb, 0, 'Première condamnation internationale pour destruction de patrimoine.', 2),
    ('54ae6014-3e43-5d7e-9e3c-288a41364636'::uuid, '878d212b-96cd-5b84-8064-d6a3093af5ab'::uuid, 'Quelle destruction de 2001 a marqué l’opinion mondiale en Afghanistan ?', 'mcq', '["Les bouddhas de Bamiyan","La citadelle d’Hérat","Le musée de Kaboul","Le minaret de Djam"]'::jsonb, 0, 'Les talibans l’ont revendiquée comme un geste idéologique.', 3),
    ('ec5c9005-0250-5248-a82c-f86858979f34'::uuid, '878d212b-96cd-5b84-8064-d6a3093af5ab'::uuid, 'Quel effet négatif le tourisme culturel de masse produit-il sur les sites patrimoniaux ?', 'mcq', '["La surfréquentation et la muséification des centres","La disparition des labels","La baisse des financements","La perte des archives"]'::jsonb, 0, 'Venise, Barcelone ou le Machu Picchu doivent réguler les flux.', 4),
    ('72822012-d189-5e62-9e3f-d0c2dff27788'::uuid, '878d212b-96cd-5b84-8064-d6a3093af5ab'::uuid, 'Que propose le rapport Sarr-Savoy de 2018 ?', 'mcq', '["La restitution d’objets acquis en contexte colonial","Le classement de nouveaux monuments","La création d’un musée européen","Un plan de restauration des cathédrales"]'::jsonb, 0, 'Il a conduit aux restitutions au Bénin en 2021.', 5),
    ('9a0a2ed1-e14e-524b-8b62-0b18098b0624'::uuid, '878d212b-96cd-5b84-8064-d6a3093af5ab'::uuid, 'La destruction du patrimoine d’un groupe peut viser à nier son existence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Mostar, Bamiyan, Palmyre : effacer les traces, c’est prolonger la guerre autrement.', 6),
    ('f1eefbfc-6445-5d02-b17e-5b7bbee26f74'::uuid, '878d212b-96cd-5b84-8064-d6a3093af5ab'::uuid, 'Quelle ville a reconstruit à l’identique sa vieille ville détruite pendant la guerre, comme affirmation nationale ?', 'mcq', '["Varsovie","Dresde","Rotterdam","Coventry"]'::jsonb, 0, 'La reconstruction elle-même est aujourd’hui inscrite au patrimoine mondial.', 7),
    ('e4d6420b-1c27-502e-a307-698c7dcdef64'::uuid, '878d212b-96cd-5b84-8064-d6a3093af5ab'::uuid, 'Que signifie le label UNESCO pour un territoire ?', 'mcq', '["Une protection, mais aussi un argument touristique et économique","Un financement automatique intégral","Une exemption de règles nationales","Une garantie contre la guerre"]'::jsonb, 0, 'La reconnaissance attire les visiteurs autant qu’elle oblige à conserver.', 8),
    ('912c3f98-e05b-566a-bf9f-bccfdaceebfe'::uuid, 'bef946cc-62d0-545c-9561-fb5402e95674'::uuid, 'Quelle conception de la restauration Viollet-le-Duc défend-il ?', 'mcq', '["Rétablir l’édifice dans un état complet, quitte à recréer","Ne jamais intervenir","Reconstruire en matériaux modernes","Déplacer les monuments menacés"]'::jsonb, 0, 'D’où les ajouts de Carcassonne ou les gargouilles de Notre-Dame.', 1),
    ('a31fb59c-4beb-541a-823e-ae8f1389785c'::uuid, 'bef946cc-62d0-545c-9561-fb5402e95674'::uuid, 'Quel penseur britannique s’oppose à la restauration au nom de l’authenticité ?', 'mcq', '["John Ruskin","William Morris uniquement","Prosper Mérimée","John Locke"]'::jsonb, 0, 'Pour lui, entretenir suffit : restaurer falsifie le témoignage du temps.', 2),
    ('0dcb0331-1f5c-58fa-b9bd-d78b2ab6904a'::uuid, 'bef946cc-62d0-545c-9561-fb5402e95674'::uuid, 'Quelle charte de 1964 fixe les principes internationaux de la restauration ?', 'mcq', '["La charte de Venise","La charte d’Athènes","La charte de Faro","La charte de Cracovie"]'::jsonb, 0, 'Authenticité des matériaux, lisibilité des interventions nouvelles.', 3),
    ('6196fe9c-558d-57f3-942f-e9b1c5ca981d'::uuid, 'bef946cc-62d0-545c-9561-fb5402e95674'::uuid, 'Que se passe-t-il si un bien inscrit est mal géré ou dénaturé ?', 'mcq', '["Il peut être retiré de la liste du patrimoine mondial","Il est automatiquement financé par l’UNESCO","Il change de catégorie","Rien, l’inscription est définitive"]'::jsonb, 0, 'Dresde en 2009 et Liverpool en 2021 en ont fait l’expérience.', 4),
    ('96525d24-3fca-5f2c-8d91-52bb3cd4afe0'::uuid, 'bef946cc-62d0-545c-9561-fb5402e95674'::uuid, 'Quel dispositif français finance la restauration de sites en péril par un jeu de hasard ?', 'mcq', '["Le Loto du patrimoine","La taxe de séjour","Le crédit d’impôt monuments","Le fonds Malraux"]'::jsonb, 0, 'Lancé en 2018, il complète les financements publics et le mécénat.', 5),
    ('203d10c4-bb8e-5802-b31f-f4bc549d9b10'::uuid, 'bef946cc-62d0-545c-9561-fb5402e95674'::uuid, 'Le changement climatique menace directement certains sites patrimoniaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Érosion côtière, montée des eaux, épisodes extrêmes : Venise en est le symbole.', 6),
    ('ebd9d4a0-8799-5959-87e6-d1f44bb11a82'::uuid, 'bef946cc-62d0-545c-9561-fb5402e95674'::uuid, 'À quoi sert la liste du patrimoine mondial en péril ?', 'mcq', '["Alerter l’opinion et mobiliser des aides internationales","Déclasser les sites abîmés","Interdire le tourisme","Transférer la propriété à l’UNESCO"]'::jsonb, 0, 'C’est un signal d’alarme, pas une sanction.', 7),
    ('d4bd9b16-c96e-578d-81d2-667f9fb1797f'::uuid, 'bef946cc-62d0-545c-9561-fb5402e95674'::uuid, 'Quel événement de 2019 a déclenché une souscription internationale en France ?', 'mcq', '["L’incendie de Notre-Dame de Paris","L’effondrement d’un pont à Gênes","Les inondations de Venise","La restauration du Panthéon"]'::jsonb, 0, 'Des centaines de millions d’euros promis en quelques jours.', 8),
    ('d0d39dfb-713d-5c42-9900-3def4a80ae46'::uuid, '40f65ef9-6beb-5ed1-a943-d56901240e08'::uuid, 'Qui crée le ministère des Affaires culturelles en 1959 ?', 'mcq', '["André Malraux","Jack Lang","Prosper Mérimée","Georges Pompidou"]'::jsonb, 0, 'Il fait du patrimoine et de sa diffusion une politique d’État à part entière.', 1),
    ('eaefe301-f90b-5111-9830-13f3bbbff8d8'::uuid, '40f65ef9-6beb-5ed1-a943-d56901240e08'::uuid, 'Que crée la loi Malraux de 1962 ?', 'mcq', '["Les secteurs sauvegardés","Les monuments historiques","Les parcs nationaux","Le Loto du patrimoine"]'::jsonb, 0, 'Elle protège des quartiers entiers, et non plus des édifices isolés.', 2),
    ('c5fe8784-dc42-50c8-ad9f-f0b494d1da65'::uuid, '40f65ef9-6beb-5ed1-a943-d56901240e08'::uuid, 'Dans quel pays sont nées les Journées européennes du patrimoine, en 1984 ?', 'mcq', '["En France","En Italie","En Allemagne","Au Royaume-Uni"]'::jsonb, 0, 'L’initiative française a ensuite été reprise dans toute l’Europe.', 3),
    ('c732199f-8ed9-51b0-8a82-3bd2f47c8e51'::uuid, '40f65ef9-6beb-5ed1-a943-d56901240e08'::uuid, 'Quel site industriel français a été inscrit au patrimoine mondial en 2012 ?', 'mcq', '["Le bassin minier du Nord-Pas-de-Calais","Les salines d’Arc-et-Senans","Le viaduc de Millau","Les chantiers de Saint-Nazaire"]'::jsonb, 0, 'La reconnaissance d’un patrimoine ouvrier et paysager.', 4),
    ('e5bdd877-e6c1-50f6-bdc9-8111223e4f7d'::uuid, '40f65ef9-6beb-5ed1-a943-d56901240e08'::uuid, 'Qu’est-ce que le fonds ALIPH, créé en 2017 ?', 'mcq', '["Un fonds international de protection du patrimoine en zone de conflit","Un fonds d’aide aux musées français","Un programme de restitution","Un label touristique"]'::jsonb, 0, 'Une initiative franco-émirienne, prolongement diplomatique du patrimoine.', 5),
    ('6eeb3684-8ec8-5193-aadd-99015e9fe69a'::uuid, '40f65ef9-6beb-5ed1-a943-d56901240e08'::uuid, 'Le Louvre Abou Dabi illustre une forme commerciale de la diplomatie culturelle française.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le nom du musée et son expertise y sont loués contre rémunération.', 6),
    ('c0ffc3cb-3503-5a58-b42a-c88ff09157b7'::uuid, '40f65ef9-6beb-5ed1-a943-d56901240e08'::uuid, 'Quel élément du patrimoine immatériel français est inscrit à l’UNESCO ?', 'mcq', '["Le repas gastronomique des Français","La Marseillaise","Le Tour de France","La langue française"]'::jsonb, 0, 'Rejoint depuis par le savoir-faire de la baguette et l’art du zinc.', 7),
    ('c62c788a-2c97-5617-a57d-7d48e8044d80'::uuid, '40f65ef9-6beb-5ed1-a943-d56901240e08'::uuid, 'Quelle tension traverse aujourd’hui la politique du patrimoine ?', 'mcq', '["Préservation contre transition énergétique et besoins en logement","Tourisme contre archéologie","État contre UNESCO","Musées contre bibliothèques"]'::jsonb, 0, 'Isolation, éoliennes en covisibilité, densification : chaque projet doit être arbitré.', 8),
    ('4ccef9a0-260e-5d5f-9541-4f1e1ad104b6'::uuid, 'd85b2ce9-e255-50a7-9619-88422c8c1ac6'::uuid, 'Qui a popularisé le terme d’anthropocène en 2000 ?', 'mcq', '["Paul Crutzen","Rachel Carson","Gro Harlem Brundtland","James Lovelock"]'::jsonb, 0, 'Le chimiste de l’atmosphère désigne ainsi une humanité devenue force géologique.', 1),
    ('ab51c6ed-feea-5e74-8f9e-3667f9c6d03c'::uuid, 'd85b2ce9-e255-50a7-9619-88422c8c1ac6'::uuid, 'Quel rapport définit en 1987 le développement durable ?', 'mcq', '["Le rapport Brundtland","Le rapport du Club de Rome","Le rapport Stern","Le rapport Meadows"]'::jsonb, 0, 'Répondre aux besoins du présent sans compromettre ceux des générations futures.', 2),
    ('452e15c1-d562-5a22-a999-5e765266aa35'::uuid, 'd85b2ce9-e255-50a7-9619-88422c8c1ac6'::uuid, 'Quelle conférence de 1972 est la première conférence mondiale sur l’environnement ?', 'mcq', '["La conférence de Stockholm","Le sommet de Rio","La COP1 de Berlin","La conférence de Kyoto"]'::jsonb, 0, 'Elle donne naissance au Programme des Nations unies pour l’environnement.', 3),
    ('9035d9e1-1d2f-543f-942d-d025c8da609c'::uuid, 'd85b2ce9-e255-50a7-9619-88422c8c1ac6'::uuid, 'Quel est le premier parc national créé au monde, en 1872 ?', 'mcq', '["Yellowstone","Yosemite","Le Kruger","La Vanoise"]'::jsonb, 0, 'Il inaugure une conception de la nature protégée par mise à l’écart.', 4),
    ('a93d1bf2-2bf7-57e0-9d2a-67000944bba0'::uuid, 'd85b2ce9-e255-50a7-9619-88422c8c1ac6'::uuid, 'Que met en avant le sommet de Rio de 1992 ?', 'mcq', '["La biodiversité, le climat et l’Agenda 21","Le protocole de Montréal","La création du GIEC","La taxe carbone"]'::jsonb, 0, 'Il installe le vocabulaire international de l’environnement.', 5),
    ('fe151980-8eed-5062-91be-babbaa7b6372'::uuid, 'd85b2ce9-e255-50a7-9619-88422c8c1ac6'::uuid, 'La notion d’environnement est une donnée naturelle, identique dans toutes les cultures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une construction culturelle et historique, variable selon les sociétés.', 6),
    ('ee195239-28bd-59c0-a84b-d6818844b2c0'::uuid, 'd85b2ce9-e255-50a7-9619-88422c8c1ac6'::uuid, 'Que désigne la « grande accélération » ?', 'mcq', '["L’emballement des pressions humaines sur la planète depuis 1950","La croissance démographique du XIXe siècle","La révolution numérique","La hausse des rendements agricoles médiévaux"]'::jsonb, 0, 'C’est l’une des dates candidates pour marquer le début de l’anthropocène.', 7),
    ('0ae4055f-6934-5993-884a-30d7783ffe7c'::uuid, 'd85b2ce9-e255-50a7-9619-88422c8c1ac6'::uuid, 'Quel rapport de 1972 alerte sur les limites de la croissance ?', 'mcq', '["Halte à la croissance ?, du Club de Rome","Le rapport Brundtland","Printemps silencieux","Le rapport du GIEC"]'::jsonb, 0, 'Le rapport Meadows modélise l’épuisement des ressources.', 8),
    ('56c2a9a6-b4ac-50fd-a3ac-1c0bd6330ed5'::uuid, '369d02ab-4349-5db9-afe0-5647df3ae2fb'::uuid, 'Quel protocole de 1987 a permis de réduire les gaz détruisant la couche d’ozone ?', 'mcq', '["Le protocole de Montréal","Le protocole de Kyoto","L’accord de Paris","La convention CITES"]'::jsonb, 0, 'C’est le succès le plus net de la coopération environnementale mondiale.', 1),
    ('2bfb2eca-a2d9-5695-be50-75674febe24a'::uuid, '369d02ab-4349-5db9-afe0-5647df3ae2fb'::uuid, 'Que vise l’accord de Kunming-Montréal de 2022 ?', 'mcq', '["Protéger 30 % des terres et des mers d’ici 2030","Interdire le charbon","Créer une taxe carbone mondiale","Limiter la pêche à 10 %"]'::jsonb, 0, 'Un objectif chiffré pour enrayer l’effondrement de la biodiversité.', 2),
    ('9a391db2-32fd-5f00-84fb-444d13af340d'::uuid, '369d02ab-4349-5db9-afe0-5647df3ae2fb'::uuid, 'Quelle convention encadre le commerce international des espèces menacées ?', 'mcq', '["La CITES","La convention de Ramsar","La convention de Bâle","La convention de Vienne"]'::jsonb, 0, 'Signée en 1973, elle réglemente ou interdit ces échanges.', 3),
    ('38e15586-1390-5b07-8860-5d0dd87bd2dd'::uuid, '369d02ab-4349-5db9-afe0-5647df3ae2fb'::uuid, 'Quel principe est inscrit dans la Charte de l’environnement française de 2005 ?', 'mcq', '["Le principe de précaution","Le principe de subsidiarité","Le principe de réciprocité","Le principe d’unanimité"]'::jsonb, 0, 'La Charte a valeur constitutionnelle depuis 2005.', 4),
    ('6c0a7e63-9237-59d4-8200-10c2965ce4f5'::uuid, '369d02ab-4349-5db9-afe0-5647df3ae2fb'::uuid, 'Qu’est-ce que la surpêche ?', 'mcq', '["Une exploitation supérieure à la capacité de renouvellement des stocks","La pêche en haute mer","La pêche pratiquée hors saison","La pêche industrielle en général"]'::jsonb, 0, 'Environ un tiers des stocks mondiaux sont dans cette situation.', 5),
    ('8b5e67ca-7e99-5f51-b671-6368b2752f49'::uuid, '369d02ab-4349-5db9-afe0-5647df3ae2fb'::uuid, 'La protection de l’environnement fait consensus entre tous les acteurs d’un territoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chaque projet oppose habitants, entreprises, ONG et États : c’est un rapport de force.', 6),
    ('9e46ac92-3b8d-51b6-8d17-841e9a01c0bd'::uuid, '369d02ab-4349-5db9-afe0-5647df3ae2fb'::uuid, 'Quelle organisation évalue à l’échelle mondiale l’état de la biodiversité ?', 'mcq', '["L’IPBES","Le GIEC","L’AIEA","L’OMC"]'::jsonb, 0, 'C’est l’équivalent du GIEC pour le vivant.', 7),
    ('70b561a2-0572-5a5b-9f9f-e5afe4593b1f'::uuid, '369d02ab-4349-5db9-afe0-5647df3ae2fb'::uuid, 'Que désigne le principe pollueur-payeur ?', 'mcq', '["Faire supporter le coût des dommages à celui qui les cause","Interdire toute pollution","Taxer les consommateurs","Indemniser les industriels"]'::jsonb, 0, 'Il vise à internaliser dans le prix le coût environnemental réel.', 8),
    ('157153ed-2257-5862-a665-a1d62e20e2c9'::uuid, '046e08c4-3cd4-56cb-92f0-5c4baa71c791'::uuid, 'En quelle année le GIEC a-t-il été créé ?', 'mcq', '["1988","1972","1997","2015"]'::jsonb, 0, 'Il évalue et synthétise l’état des connaissances scientifiques sur le climat.', 1),
    ('edafc074-eb3c-50a9-b063-d103ad792124'::uuid, '046e08c4-3cd4-56cb-92f0-5c4baa71c791'::uuid, 'Quel accord de 2015 fixe l’objectif de contenir le réchauffement nettement sous 2 °C ?', 'mcq', '["L’accord de Paris","Le protocole de Kyoto","L’accord de Copenhague","La convention de Rio"]'::jsonb, 0, 'Universel, mais fondé sur des engagements volontaires des États.', 2),
    ('3c8bbc65-79eb-5ae1-855a-023fc92261a1'::uuid, '046e08c4-3cd4-56cb-92f0-5c4baa71c791'::uuid, 'Quelle limite majeure affectait le protocole de Kyoto ?', 'mcq', '["Il ne contraignait que les pays développés et les États-Unis ne l’ont pas ratifié","Il était trop contraignant pour tous","Il ne visait que le méthane","Il n’a jamais été signé"]'::jsonb, 0, 'D’où le changement d’architecture retenu à Paris en 2015.', 3),
    ('967d167f-6b7f-577d-a843-f332adf6f699'::uuid, '046e08c4-3cd4-56cb-92f0-5c4baa71c791'::uuid, 'Qu’appelle-t-on le Petit Âge glaciaire ?', 'mcq', '["Une période de refroidissement du XIVe au XIXe siècle","La dernière glaciation","Un épisode volcanique","Le refroidissement des années 1970"]'::jsonb, 0, 'Il rappelle que le climat variait déjà avant l’ère industrielle — mais bien plus lentement.', 4),
    ('161e366d-9bdf-5674-90fc-cf0f586d79dd'::uuid, '046e08c4-3cd4-56cb-92f0-5c4baa71c791'::uuid, 'Que désigne le principe de « responsabilités communes mais différenciées » ?', 'mcq', '["Tous les États sont concernés, mais pas au même degré","Seuls les pays du Sud sont responsables","Chaque État agit seul","Les entreprises sont seules responsables"]'::jsonb, 0, 'Il tient compte des émissions historiques et des capacités de chacun.', 5),
    ('e30907cb-4321-59d8-8600-37ece6267cd1'::uuid, '046e08c4-3cd4-56cb-92f0-5c4baa71c791'::uuid, 'Les mesures de CO₂ de Mauna Loa ont montré une hausse continue de sa concentration.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La courbe de Keeling, commencée en 1958, est l’une des preuves les plus parlantes.', 6),
    ('116879d4-7acf-55e4-a503-a9a945ed6497'::uuid, '046e08c4-3cd4-56cb-92f0-5c4baa71c791'::uuid, 'Quel fonds a été créé en 2022 pour aider les pays les plus vulnérables ?', 'mcq', '["Le fonds « pertes et dommages »","Le Fonds vert","Le fonds ALIPH","Le fonds carbone"]'::jsonb, 0, 'Il reconnaît que certains dommages climatiques ne sont plus évitables.', 7),
    ('e0634b2b-b1b2-5c83-a8f7-7247d08f46a6'::uuid, '046e08c4-3cd4-56cb-92f0-5c4baa71c791'::uuid, 'Pourquoi le climat est-il un problème géopolitique et pas seulement scientifique ?', 'mcq', '["Parce que responsabilités et effets sont inégalement répartis","Parce que la science est incertaine","Parce qu’il ne concerne que l’Arctique","Parce qu’aucun État ne l’a reconnu"]'::jsonb, 0, 'Négocier le climat revient à partager un budget carbone, donc un droit à se développer.', 8),
    ('368bc243-488a-5515-8f47-87ec93039e4d'::uuid, 'b58f8726-8e55-5433-8b87-a628c117dcec'::uuid, 'Quel ouvrage de Rachel Carson lance l’écologie moderne en 1962 ?', 'mcq', '["Printemps silencieux","Halte à la croissance ?","La Terre vue du ciel","Notre avenir à tous"]'::jsonb, 0, 'Il dénonce les effets des pesticides, à commencer par le DDT.', 1),
    ('d5d27b65-14f6-5c4b-91ca-01745d037b3b'::uuid, 'b58f8726-8e55-5433-8b87-a628c117dcec'::uuid, 'Quelle agence fédérale de protection de l’environnement est créée en 1970 ?', 'mcq', '["L’EPA","La NOAA","Le NPS","La FEMA"]'::jsonb, 0, 'Créée sous Nixon, elle applique le Clean Air Act et le Clean Water Act.', 2),
    ('6d895b88-4229-5a71-929c-5996e2d8cb55'::uuid, 'b58f8726-8e55-5433-8b87-a628c117dcec'::uuid, 'Quelle décision Donald Trump prend-il en 2017 concernant le climat ?', 'mcq', '["Le retrait des États-Unis de l’accord de Paris","Le retrait du protocole de Kyoto","La fermeture de l’EPA","La ratification de Kyoto"]'::jsonb, 0, 'Effectif en 2020, il est annulé par Joe Biden dès 2021.', 3),
    ('2e2d6f68-93a8-55f2-a20b-a4d067038998'::uuid, 'b58f8726-8e55-5433-8b87-a628c117dcec'::uuid, 'Quel plan d’investissement climatique les États-Unis adoptent-ils en 2022 ?', 'mcq', '["L’Inflation Reduction Act","Le Green New Deal","Le Clean Power Plan","L’American Rescue Plan"]'::jsonb, 0, 'Le plus important effort d’investissement climatique de leur histoire.', 4),
    ('82c01cb8-810d-50d2-9824-1ef9e9820fcd'::uuid, 'b58f8726-8e55-5433-8b87-a628c117dcec'::uuid, 'Que désigne la notion de wilderness dans la culture américaine ?', 'mcq', '["Une nature sauvage à préserver de toute exploitation","Une zone agricole protégée","Un parc urbain","Une réserve indienne"]'::jsonb, 0, 'Elle fonde la conception américaine du parc national.', 5),
    ('ecb58fcd-0810-562d-b456-6db9b1b19882'::uuid, 'b58f8726-8e55-5433-8b87-a628c117dcec'::uuid, 'Les États-Unis sont le premier émetteur mondial de CO₂ en émissions cumulées depuis 1850.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Devant la Chine, qui est aujourd’hui le premier émetteur annuel.', 6),
    ('f2bc105e-1ae9-5770-96cb-bbddb1e7d9af'::uuid, 'b58f8726-8e55-5433-8b87-a628c117dcec'::uuid, 'Quelle révolution énergétique a fait des États-Unis un exportateur d’hydrocarbures ?', 'mcq', '["Le gaz de schiste","Le nucléaire civil","L’éolien offshore","Le charbon propre"]'::jsonb, 0, 'La fracturation hydraulique a bouleversé leur bilan énergétique.', 7),
    ('4377be78-d95e-55c1-a9ed-cb713a5261ed'::uuid, 'b58f8726-8e55-5433-8b87-a628c117dcec'::uuid, 'Quel échelon institutionnel permet aux États-Unis d’agir même quand l’État fédéral recule ?', 'mcq', '["Les États fédérés et les villes","Le Sénat seul","La Cour suprême seule","Le Pentagone"]'::jsonb, 0, 'La Californie impose par exemple ses propres normes d’émissions.', 8),
    ('f2b6cc58-28d5-5191-897c-1990705116bd'::uuid, 'f62fdfd1-3eac-5b61-815e-917e78813beb'::uuid, 'Quelle invention du milieu du XVe siècle accélère la diffusion des savoirs en Europe ?', 'mcq', '["L’imprimerie de Gutenberg","Le télescope","La machine à vapeur","Le papier"]'::jsonb, 0, 'Elle rend possible une circulation des textes sans précédent.', 1),
    ('35d5e337-5237-5125-8f80-c97064f85b76'::uuid, 'f62fdfd1-3eac-5b61-815e-917e78813beb'::uuid, 'Quel modèle universitaire, né en 1810, associe enseignement et recherche ?', 'mcq', '["Le modèle Humboldt","Le modèle napoléonien","Le modèle d’Oxford","Le modèle jésuite"]'::jsonb, 0, 'Il inspire les universités de recherche du monde entier.', 2),
    ('7d29673f-7279-5743-b63e-5d412bc4520c'::uuid, 'f62fdfd1-3eac-5b61-815e-917e78813beb'::uuid, 'Quel objectif de R&D la stratégie de Lisbonne fixe-t-elle en 2000 ?', 'mcq', '["3 % du PIB consacrés à la recherche","10 % du PIB","1 % du PIB","Aucun objectif chiffré"]'::jsonb, 0, 'Un objectif que la plupart des États européens n’ont pas atteint.', 3),
    ('26aa1ce2-48e7-568f-9eaf-9ca59e6eac99'::uuid, 'f62fdfd1-3eac-5b61-815e-917e78813beb'::uuid, 'Qu’est-ce que la fuite des cerveaux ?', 'mcq', '["Le départ de chercheurs qualifiés vers les pays les mieux dotés","La perte d’archives scientifiques","L’abandon des études supérieures","La fermeture de laboratoires"]'::jsonb, 0, 'Elle prive les pays de départ du bénéfice de la formation qu’ils ont financée.', 4),
    ('473086cf-3c2c-583c-b582-289afbd5db8e'::uuid, 'f62fdfd1-3eac-5b61-815e-917e78813beb'::uuid, 'Quelles lois rendent l’école primaire obligatoire et gratuite en France ?', 'mcq', '["Les lois Ferry (1881-1882)","La loi Guizot (1833)","La loi Haby (1975)","La loi Debré (1959)"]'::jsonb, 0, 'Un jalon décisif de la diffusion du savoir à toute une société.', 5),
    ('1a969e87-31d1-51f9-8f1b-8edbd9757a5f'::uuid, 'f62fdfd1-3eac-5b61-815e-917e78813beb'::uuid, 'Dans une économie de la connaissance, la croissance repose surtout sur l’immatériel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'R&D, brevets, logiciels et formation en sont les principaux moteurs.', 6),
    ('2d0854fb-5e15-516b-916d-84998115b77a'::uuid, 'f62fdfd1-3eac-5b61-815e-917e78813beb'::uuid, 'Quel ouvrage du XVIIIe siècle incarne le projet de rassembler et diffuser tous les savoirs ?', 'mcq', '["L’Encyclopédie de Diderot et d’Alembert","Le Dictionnaire de l’Académie","La Somme théologique","Les Essais de Montaigne"]'::jsonb, 0, 'Un projet éditorial et politique autant que scientifique.', 7),
    ('91de4502-51a6-5350-a02d-0deca7b9a593'::uuid, 'f62fdfd1-3eac-5b61-815e-917e78813beb'::uuid, 'Quel acteur privé finance aujourd’hui une part croissante de la recherche en intelligence artificielle ?', 'mcq', '["Les grandes entreprises du numérique","Les fondations religieuses","Les collectivités locales","Les organisations syndicales"]'::jsonb, 0, 'Ce qui déplace hors des États une partie du pilotage de la recherche.', 8),
    ('92b536d6-6176-54c7-9d97-2ccc9cfd444c'::uuid, 'e5f5e7e6-493d-5cfe-9c68-537bea054bc5'::uuid, 'Comment s’appelle l’évaluation d’un article scientifique par d’autres chercheurs avant publication ?', 'mcq', '["L’évaluation par les pairs","L’audit externe","Le contrôle éditorial","La certification"]'::jsonb, 0, 'C’est la procédure de base du contrôle de qualité scientifique.', 1),
    ('aca74171-725e-5903-bfad-b02cce5ad281'::uuid, 'e5f5e7e6-493d-5cfe-9c68-537bea054bc5'::uuid, 'Quel pays est devenu le premier producteur mondial d’articles scientifiques en volume ?', 'mcq', '["La Chine","Les États-Unis","Le Japon","L’Allemagne"]'::jsonb, 0, 'Elle est aussi le premier déposant mondial de brevets.', 2),
    ('f7c8a1e4-a2bd-50d1-b897-634f7e8fdbdc'::uuid, 'e5f5e7e6-493d-5cfe-9c68-537bea054bc5'::uuid, 'Que défend le mouvement de l’open access ?', 'mcq', '["L’accès gratuit aux résultats de la recherche","La suppression des brevets","La publication en anglais uniquement","La fermeture des archives"]'::jsonb, 0, 'Il s’oppose au modèle payant des grands éditeurs scientifiques.', 3),
    ('cf588c47-6d40-5832-b392-a36e7b405a32'::uuid, 'e5f5e7e6-493d-5cfe-9c68-537bea054bc5'::uuid, 'Quel grand équipement européen illustre la coopération scientifique internationale ?', 'mcq', '["Le CERN","Le CNRS","La NASA","L’INSERM"]'::jsonb, 0, 'Comme ITER ou l’ISS, il dépasse les moyens d’un seul État.', 4),
    ('6ff9a8f6-6806-5ec5-81c5-36ee83e354a6'::uuid, 'e5f5e7e6-493d-5cfe-9c68-537bea054bc5'::uuid, 'Quel débat mondial la pandémie de Covid-19 a-t-elle relancé sur la diffusion du savoir ?', 'mcq', '["Celui des brevets sur les vaccins","Celui des revues prédatrices","Celui de la fuite des cerveaux","Celui du financement des universités"]'::jsonb, 0, 'Protéger l’innovation ou permettre l’accès : l’arbitrage est politique.', 5),
    ('4c26ad74-93d2-5e69-b71e-dd17f5c30137'::uuid, 'e5f5e7e6-493d-5cfe-9c68-537bea054bc5'::uuid, 'L’Afrique subsaharienne représente moins de 1 % de la production scientifique mondiale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un écart qui traduit la concentration des financements de la recherche.', 6),
    ('ad707779-b8d2-51d0-9ed6-c23be3c8b05c'::uuid, 'e5f5e7e6-493d-5cfe-9c68-537bea054bc5'::uuid, 'Qu’est-ce qu’une revue prédatrice ?', 'mcq', '["Une revue qui publie contre paiement sans réelle évaluation scientifique","Une revue réservée aux militaires","Une revue à accès payant","Une revue interdisant la citation"]'::jsonb, 0, 'Elle profite de la pression à publier et affaiblit la crédibilité de la science.', 7),
    ('65d652d8-2727-560c-b172-f80e4cb24aa8'::uuid, 'e5f5e7e6-493d-5cfe-9c68-537bea054bc5'::uuid, 'Quelle stratégie a été employée par certaines industries pour retarder des décisions publiques ?', 'mcq', '["La mise en doute organisée des résultats scientifiques","Le financement de l’open access","La publication systématique des données","Le dépôt de brevets libres"]'::jsonb, 0, 'Le tabac puis le climat en offrent les exemples les mieux documentés.', 8),
    ('9584b1ea-35b5-55d7-a341-00e30bfe2575'::uuid, 'e4135bca-1532-5339-8959-4858d5058f42'::uuid, 'Qu’est-ce que le lyssenkisme ?', 'mcq', '["Une doctrine imposée par le pouvoir soviétique qui a ruiné la génétique","Une théorie physique russe","Un mouvement d’ouverture scientifique","Une méthode agricole reconnue"]'::jsonb, 0, 'Un cas d’école de science soumise à l’idéologie.', 1),
    ('97aee891-5e06-5513-8d1a-d5ce42d749cc'::uuid, 'e4135bca-1532-5339-8959-4858d5058f42'::uuid, 'Quel programme illustre l’alliance de l’État, de l’armée et de la science pendant la Seconde Guerre mondiale ?', 'mcq', '["Le projet Manhattan","Le plan Marshall","L’opération Overlord","Le programme Apollo"]'::jsonb, 0, 'Il aboutit à la bombe atomique en 1945.', 2),
    ('8b4d7663-5645-52c0-9ce3-bf9f91af066b'::uuid, 'e4135bca-1532-5339-8959-4858d5058f42'::uuid, 'Sur quelle technologie porte aujourd’hui une part majeure de la rivalité sino-américaine ?', 'mcq', '["Les semi-conducteurs","Le textile","La sidérurgie","L’agroalimentaire"]'::jsonb, 0, 'Contrôles à l’exportation et subventions massives de part et d’autre.', 3),
    ('e87bbee0-7b28-54f0-b841-3769acb828e8'::uuid, 'e4135bca-1532-5339-8959-4858d5058f42'::uuid, 'Quel instrument la Chine utilise-t-elle pour diffuser sa langue et son influence culturelle ?', 'mcq', '["Les instituts Confucius","Les instituts Cervantès","Les Alliances françaises","Le British Council"]'::jsonb, 0, 'Le savoir et la langue comme leviers de soft power.', 4),
    ('727e678d-1d02-5706-b9a5-b054c8dc33b8'::uuid, 'e4135bca-1532-5339-8959-4858d5058f42'::uuid, 'Quelle opération a permis aux États-Unis de récupérer des scientifiques allemands après 1945 ?', 'mcq', '["L’opération Paperclip","L’opération Overlord","L’opération Torch","L’opération Barbarossa"]'::jsonb, 0, 'Les savants sont devenus eux-mêmes une ressource stratégique.', 5),
    ('3624d01a-a34c-56d1-ad3b-2ae6dc6fdcaa'::uuid, 'e4135bca-1532-5339-8959-4858d5058f42'::uuid, 'Un régime politique peut infléchir durablement le contenu de la recherche scientifique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le lyssenkisme soviétique et la « science aryenne » nazie en sont les preuves.', 6),
    ('24a6c255-5ead-557c-a751-c16d37164622'::uuid, 'e4135bca-1532-5339-8959-4858d5058f42'::uuid, 'À quoi sert un classement international d’universités comme celui de Shanghai ?', 'mcq', '["Il alimente la compétition et l’attractivité des systèmes universitaires","Il répartit les financements de l’ONU","Il fixe les programmes scolaires","Il délivre des diplômes"]'::jsonb, 0, 'Ces classements sont contestés, mais très utilisés par les États et les étudiants.', 7),
    ('62ec8f8f-2f2b-56a2-9b9b-f0bf78db78be'::uuid, 'e4135bca-1532-5339-8959-4858d5058f42'::uuid, 'Quel procès reste le symbole du conflit entre autorité et démonstration scientifique ?', 'mcq', '["Le procès de Galilée","Le procès de Nuremberg","Le procès Dreyfus","Le procès du singe"]'::jsonb, 0, 'Condamné en 1633 pour avoir défendu l’héliocentrisme.', 8),
    ('388a9c2c-14a7-5e6a-8a63-7ade95cfac35'::uuid, '137e1cc8-f34c-5ad7-bd19-8aea1d88cdf1'::uuid, 'Quel réseau, ancêtre d’Internet, naît en 1969 d’un programme militaire américain ?', 'mcq', '["ARPANET","Minitel","Usenet","Ethernet"]'::jsonb, 0, 'Cette origine explique le poids durable des États-Unis dans la gouvernance du réseau.', 1),
    ('4ee1f2de-e328-5ba9-a7de-571473d5484b'::uuid, '137e1cc8-f34c-5ad7-bd19-8aea1d88cdf1'::uuid, 'Qui invente le World Wide Web au CERN entre 1989 et 1991 ?', 'mcq', '["Tim Berners-Lee","Vinton Cerf","Steve Jobs","Alan Turing"]'::jsonb, 0, 'Il choisit de le placer dans le domaine public, ce qui accélère sa diffusion.', 2),
    ('4694b426-16cc-5fa7-a718-d0b51e496be6'::uuid, '137e1cc8-f34c-5ad7-bd19-8aea1d88cdf1'::uuid, 'Quelles sont les trois couches du cyberespace ?', 'mcq', '["Matérielle, logicielle et sémantique","Publique, privée et militaire","Locale, nationale et mondiale","Fixe, mobile et satellitaire"]'::jsonb, 0, 'La couche matérielle rappelle que le « virtuel » repose sur des câbles bien réels.', 3),
    ('53889d95-ad16-5bde-9d8c-ffd32d8f6615'::uuid, '137e1cc8-f34c-5ad7-bd19-8aea1d88cdf1'::uuid, 'Quel règlement européen de 2018 encadre la protection des données personnelles ?', 'mcq', '["Le RGPD","Le DSA","Le DMA","Le Cloud Act"]'::jsonb, 0, 'L’Union européenne impose par la norme ce qu’elle ne domine pas par la technique.', 4),
    ('386b806f-af35-5abb-b50f-7aed4cba3bb6'::uuid, '137e1cc8-f34c-5ad7-bd19-8aea1d88cdf1'::uuid, 'Qu’a révélé Edward Snowden en 2013 ?', 'mcq', '["Un système de surveillance de masse des communications","Une cyberattaque russe","Le code source de Windows","Un trafic de données médicales"]'::jsonb, 0, 'Les révélations ont durablement pesé sur les relations entre alliés.', 5),
    ('675e971c-533e-5d58-8477-ba89474294a5'::uuid, '137e1cc8-f34c-5ad7-bd19-8aea1d88cdf1'::uuid, 'Le cyberespace échappe totalement au contrôle des États.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chine, Russie et Union européenne y imposent chacune leurs règles : on parle de fragmentation.', 6),
    ('133d9400-3b04-5d47-a924-9a67fdf6dae2'::uuid, '137e1cc8-f34c-5ad7-bd19-8aea1d88cdf1'::uuid, 'Quelle convention de 2001 organise la coopération contre la cybercriminalité ?', 'mcq', '["La convention de Budapest","La convention de La Haye","La convention de Vienne","La convention de Genève"]'::jsonb, 0, 'L’un des rares cadres juridiques internationaux en la matière.', 7),
    ('13dc68e4-4835-5eed-a506-249da306e73c'::uuid, '137e1cc8-f34c-5ad7-bd19-8aea1d88cdf1'::uuid, 'En quelle année l’OTAN a-t-elle reconnu le cyber comme un domaine d’opérations militaires ?', 'mcq', '["2016","2001","2007","2022"]'::jsonb, 0, 'Au même titre que la terre, la mer, l’air et l’espace.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('hggsp');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('hggsp')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 256 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 256 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
